"""Apply a JSON Patch (RFC 6902) to a JSON document. See task.md."""

from __future__ import annotations

import re
from typing import Any


class PatchError(ValueError):
    """Raised when a patch is malformed or cannot be applied."""


_OPS = ("add", "remove", "replace", "move", "copy", "test")
_ARRAY_INDEX = re.compile(r"0|[1-9][0-9]*")
_ESCAPE = re.compile(r"~([01])")
_BAD_ESCAPE = re.compile(r"~(?![01])")


def apply(document: Any, patch: list[dict]) -> Any:
    """Return the result of applying `patch` to `document`."""
    if not isinstance(patch, list):
        raise PatchError("patch must be a list")
    result = _clone(document)
    for operation in patch:
        result = _apply_operation(result, operation)
    return result


def _apply_operation(doc: Any, operation: Any) -> Any:
    if not isinstance(operation, dict):
        raise PatchError("each operation must be an object")
    op = operation.get("op")
    if not isinstance(op, str) or op not in _OPS:
        raise PatchError(f"unknown operation {op!r}")
    path = _string(operation, "path")
    tokens = _tokens(path)

    if op == "add":
        return _add(doc, tokens, _clone(_value(operation)))
    if op == "remove":
        _remove(doc, tokens)
        return doc
    if op == "replace":
        return _replace(doc, tokens, _clone(_value(operation)))
    if op == "test":
        if not _equal(_lookup(doc, tokens), _value(operation)):
            raise PatchError(f"test failed at {path!r}")
        return doc

    source = _string(operation, "from")
    source_tokens = _tokens(source)
    if op == "copy":
        return _add(doc, tokens, _clone(_lookup(doc, source_tokens)))

    _lookup(doc, source_tokens)
    if path == source:
        return doc
    if path.startswith(source + "/"):
        raise PatchError(f"cannot move {source!r} into its own child {path!r}")
    moved = _remove(doc, source_tokens)
    return _add(doc, tokens, moved)


def _string(operation: dict, name: str) -> str:
    value = operation.get(name)
    if not isinstance(value, str):
        raise PatchError(f"{name!r} must be a string")
    return value


def _value(operation: dict) -> Any:
    if "value" not in operation:
        raise PatchError("operation requires a value")
    return operation["value"]


def _tokens(pointer: str) -> list[str]:
    if pointer == "":
        return []
    if not pointer.startswith("/"):
        raise PatchError(f"pointer {pointer!r} must start with '/'")
    tokens = []
    for raw in pointer[1:].split("/"):
        if _BAD_ESCAPE.search(raw):
            raise PatchError(f"invalid escape in pointer {pointer!r}")
        tokens.append(_ESCAPE.sub(lambda m: "/" if m.group(1) == "1" else "~", raw))
    return tokens


def _parse_index(token: str) -> int:
    # No list can be this long, and int() rejects very long digit strings.
    if not _ARRAY_INDEX.fullmatch(token) or len(token) > 18:
        raise PatchError(f"{token!r} is not an array index")
    return int(token)


def _existing(container: dict | list, token: str) -> str | int:
    if isinstance(container, dict):
        if token not in container:
            raise PatchError(f"no member {token!r}")
        return token
    index = _parse_index(token)
    if index >= len(container):
        raise PatchError(f"index {index} is out of range")
    return index


def _child(node: Any, token: str) -> Any:
    if not isinstance(node, (dict, list)):
        raise PatchError(f"cannot descend into {token!r}")
    return node[_existing(node, token)]


def _lookup(doc: Any, tokens: list[str]) -> Any:
    node = doc
    for token in tokens:
        node = _child(node, token)
    return node


def _parent(doc: Any, tokens: list[str]) -> dict | list:
    parent = _lookup(doc, tokens[:-1])
    if not isinstance(parent, (dict, list)):
        raise PatchError("parent of the target does not exist")
    return parent


def _add(doc: Any, tokens: list[str], value: Any) -> Any:
    if not tokens:
        return value
    parent = _parent(doc, tokens)
    last = tokens[-1]
    if isinstance(parent, dict):
        parent[last] = value
    else:
        parent.insert(_insertion_index(parent, last), value)
    return doc


def _insertion_index(array: list, token: str) -> int:
    if token == "-":
        return len(array)
    index = _parse_index(token)
    if index > len(array):
        raise PatchError(f"index {index} is out of range")
    return index


def _remove(doc: Any, tokens: list[str]) -> Any:
    if not tokens:
        raise PatchError("the whole document cannot be removed")
    parent = _parent(doc, tokens)
    return parent.pop(_existing(parent, tokens[-1]))


def _replace(doc: Any, tokens: list[str], value: Any) -> Any:
    if not tokens:
        return value
    parent = _parent(doc, tokens)
    parent[_existing(parent, tokens[-1])] = value
    return doc


def _equal(a: Any, b: Any) -> bool:
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(_equal(x, y) for x, y in zip(a, b))
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(_equal(a[k], b[k]) for k in a)
    return type(a) is type(b) and a == b


def _clone(value: Any) -> Any:
    if isinstance(value, dict):
        return {key: _clone(item) for key, item in value.items()}
    if isinstance(value, list):
        return [_clone(item) for item in value]
    return value
